changeSet.sql:
CREATE UNIQUE INDEX uq_organization_email ON organizations (email) WHERE email IS NOT NULL;
DROP INDEX IF EXISTS idx_contractor_organization_fk;
CREATE UNIQUE INDEX uq_contractor_project_organization ON contractors (project_id, organization_id) WHERE organization_id IS NOT NULL;
CREATE UNIQUE INDEX uq_contractor_project_email ON contractors (project_id, email) WHERE email IS NOT NULL;

rollback.sql:
DROP INDEX IF EXISTS uq_organization_email;
DROP INDEX IF EXISTS uq_contractor_project_organization;
DROP INDEX IF EXISTS uq_contractor_project_email;
CREATE INDEX idx_contractor_organization_fk ON contractors (organization_id);
